/**
 * Regenerate lib/patchNotesLoader.js when new patchnotesobN.json files are added.
 * Usage: node scripts/generate-patch-notes-loader.js
 */
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const outPath = path.join(root, 'lib', 'patchNotesLoader.js');
const patchDir = path.join(root, 'app', 'data', 'Patch Notes');

const numbers = fs
  .readdirSync(patchDir)
  .map((f) => f.match(/^patchnotesob(\d+)\.json$/))
  .filter(Boolean)
  .map((m) => Number(m[1]))
  .sort((a, b) => a - b);

const lines = [
  '/** Auto-generated by scripts/generate-patch-notes-loader.js — do not edit by hand */',
  'const OPEN_BETA_PATCH_FILES = {',
];
for (const n of numbers) {
  lines.push(`  ${n}: require('../app/data/Patch Notes/patchnotesob${n}.json'),`);
}
lines.push(
  '};',
  '',
  'function loadOpenBetaPatch(patchNumber) {',
  '  return OPEN_BETA_PATCH_FILES[patchNumber] ?? null;',
  '}',
  '',
  'module.exports = {',
  '  OPEN_BETA_PATCH_FILES,',
  '  loadOpenBetaPatch,',
  '};',
  ''
);

fs.writeFileSync(outPath, lines.join('\n'));
console.log(`Wrote ${outPath} (${numbers.length} patches)`);
